#include "stdafx.h"#include "AlarmClient.h"#include <CommonH.h>#include <Names.h>#include <rsuNoNames.h>#include <MemoryServiceH5xx.h>KAlarmClient::KAlarmClient( LPSTR _ObjName ) :	IBaseModel ( _ObjName ), m_pSystem( NULL ), m_pCBSystem( NULL ){  TypeObj = RSU_Obj;}KNoName g_Objs;static CBase* _StructFinder( LPCSTR ObjName, DWORD TypeID, int number ){  return g_Objs.FindStruct( ObjName, TypeID, number );}int KAlarmClient::Init( int ){  g_Objs = KNoName::Create( "H5xx_Objs", false );  KMemoryServiceH5xx::Instance().InitObjectsStructAllocator( NULL, NULL, _StructFinder );  m_pSystem = ::GetSystemData();  m_pCBSystem = GetControlBuilderHSystemData();  int r = KRsuSharedClient::InitializeServer( "AlarmsHW5xx_Server", ObjName );  if( r )    return 1;  return 0;}int KAlarmClient::Step0(){  return KRsuSharedClient::StepAfterInit();}int KAlarmClient::Step1(){  return KRsuSharedClient::StepAfterRestored();}int KAlarmClient::StepT(double dt){  if( m_pSystem && m_pCBSystem )  {    m_pCBSystem->timeB = m_pSystem->TimeB();    m_pCBSystem->timeM = m_pSystem->TimeM();    m_pCBSystem->nStep = m_pSystem->m_nStep;  }  double dtMs = dt * 3600. * 1000;  return KRsuSharedClient::CalcStep( (int)dtMs );}